/**
 * Pick the port forward that actually serves a game server's own port, not
 * just the first one on the record — a customer can add extra forwards
 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
 * mistaken for the game's real connect port. Falls back to the first forward
 * if none matches, so a server whose family isn't in GAME_PORT (or has no
 * exact-matching forward yet) still shows *something* rather than nothing.
 * Single shared helper so the provisioning-overlay connect string, the header
 * connect string, and the custom-domain DNS instructions can never drift from
 * each other the way three independent inline copies previously could.
 */
function gameForwardFor(server: {
  portForwards: { guestPort: number; publicPort: number }[];
  osTemplate: { family?: string | null };
  gamePlan?: { gameFamily?: string | null } | null;
}): { guestPort: number; publicPort: number } | undefined {
  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
  return server.portForwards.find((f) => f.guestPort === expectedPort) ?? server.portForwards[0];
}

function fmtUptime(seconds: number): string {
  if (!seconds || seconds <= 0) return "—";
  const d = Math.floor(seconds / 86400);
  const h = Math.floor((seconds % 86400) / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
}

type LiveStats = {
