              <span className="font-semibold">
                {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
              </span>
            </div>
            <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
          </div>
          <div className="flex justify-between">
            <span className="text-slate-400">Uptime</span>
            <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-slate-400">Network I/O</span>
            <span className="font-mono text-xs">
              {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
            </span>
          </div>
        </div>
      ) : (
        <p className="text-sm text-slate-400">
          {pveUnavailable
            ? "Hypervisor is briefly unavailable — stats will reappear shortly."
            : "Live stats appear once the server is provisioned."}
        </p>
      )}
    </div>

    <div className="card">
      <h2 className="mb-4 font-semibold">Configuration</h2>
      <dl className="space-y-2.5 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-400">Plan</dt>
          <dd>
            {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
            {totalDiskGB} GB NVMe
            {server.extraDiskGB > 0 && (
              <span className="block text-xs text-slate-500">
                {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
              </span>
            )}
          </dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Bandwidth</dt>
          <dd>{server.plan.bandwidthTB} TB / month</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Operating system</dt>
          <dd>{server.osTemplate.name}</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Created</dt>
          <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
          <dd>
            {server.isFree
              ? "Free — never expires"
              : server.expiresAt
                ? server.expiresAt.toISOString().slice(0, 10)
