"use client";

import { useState } from "react";
import { WebsitesPanel } from "./WebsitesPanel";
import { DatabasesPanel } from "./DatabasesPanel";
import { AppsPanel } from "./AppsPanel";
import { CronServicesPanel } from "./CronServicesPanel";

const SUBTABS = [
  { key: "websites", label: "Websites & PHP" },
  { key: "databases", label: "Databases" },
  { key: "apps", label: "One-click apps" },
  { key: "services", label: "Cron & Services" },
] as const;

/**
 * Grouped "Control panel" tab on the server detail page — a cPanel/Plesk-style
 * manager for the customer's own VPS, themed to match Nxeon. Keeps the four
 * bundles behind a single main tab with lightweight inner tabs so the page stays
 * readable. Each panel loads its own data client-side (loading/empty/error
 * states throughout) via the sandbox-gated server actions.
 */
export function ControlPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [tab, setTab] = useState<string>("websites");

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-1.5">
        {SUBTABS.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
                  : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "websites" && <WebsitesPanel serverId={serverId} running={running} />}
        {tab === "databases" && <DatabasesPanel serverId={serverId} running={running} />}
        {tab === "apps" && <AppsPanel serverId={serverId} running={running} />}
        {tab === "services" && <CronServicesPanel serverId={serverId} running={running} />}
      </div>
    </div>
  );
}
