export const dynamic = "force-dynamic";

export default async function CustomerInvoices() {
  const user = await requireUser();
  const invoices = await db.invoice.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 200,
  });
  // One settings read for the whole list; the prefix is per-platform, not per-invoice.
  const { numberPrefix } = await invoiceBranding();

  const openCents = invoices
    .filter((i) => i.status === "OPEN")
    .reduce((s, i) => s + i.amountCents, 0);
  const paidCents = invoices
    .filter((i) => i.status === "PAID")
    .reduce((s, i) => s + i.amountCents, 0);

  return (
    <div className="space-y-6">
      <PortalHero variant="invoices" title="Invoices" sub="Billing documents for your servers and services.">
        <Link href="/dashboard/billing" className="btn-ghost py-1.5">
          Back to billing
        </Link>
      </PortalHero>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
        <StatCard label="Invoices" value={String(invoices.length)} />
        <StatCard label="Outstanding" value={fmtMoney(openCents)} delta="open invoices" deltaGood={false} />
        <StatCard label="Paid · lifetime" value={fmtMoney(paidCents)} />
      </div>

      {invoices.length === 0 ? (
        <EmptyState
          title="No invoices yet"
          sub="Invoices for paid servers and services will appear here once issued."
        />
      ) : (
        <div className="card overflow-x-auto p-0">
          <p className="section-label px-4 pt-4">All invoices</p>
          <table className="table-shell mt-2 min-w-[640px]">
            <thead>
              <tr>
                <th>Number</th>
                <th>Description</th>
                <th>Status</th>
                <th>Method</th>
                <th className="text-right">Amount</th>
                <th className="text-right">Issued</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {invoices.map((inv) => (
                <tr key={inv.id}>
                  <td className="font-mono text-xs text-slate-300">
                    <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-brand-300">
                      {formatInvoiceNumber(inv.number, numberPrefix)}
                    </Link>
                  </td>
                  <td className="max-w-xs truncate">
                    <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-brand-300">
                      {inv.description}
                    </Link>
                  </td>
                  <td>
                    <InvoiceStatusBadge status={inv.status} />
                  </td>
                  <td className="text-slate-400">
                    {/* Card snapshot on the invoice, falling back to the user's current
                        card for pre-snapshot invoices. */}
                    {(inv.status === "PAID" || inv.status === "REFUNDED") &&
                    (inv.paidLast4 ?? user.cardLast4) ? (
                      <span className="whitespace-nowrap">
                        {brandLabel(inv.paidBrand ?? user.cardBrand)} ···· {inv.paidLast4 ?? user.cardLast4}
                      </span>
                    ) : (
                      <span className="text-slate-500">—</span>
                    )}
                  </td>
                  <td className="text-right font-mono">{fmtMoney(inv.amountCents)}</td>
                  <td className="text-right text-slate-400" title={inv.createdAt.toISOString()}>
                    {timeAgo(inv.createdAt)}
                  </td>
                  <td className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <DownloadInvoicePdfButton id={inv.id} label="PDF" className="btn-ghost py-1 text-xs" />
                      <DownloadInvoiceButton id={inv.id} label="HTML" className="btn-ghost py-1 text-xs" />
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

