/** Local-time first/last day of the current month grid (6 weeks), so the
 *  initial fetch matches the Month view the client opens on. */
function initialRange(): [string, string] {
  const now = new Date();
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const gridStart = new Date(firstOfMonth);
  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
  const gridEnd = new Date(gridStart);
  gridEnd.setDate(gridEnd.getDate() + 42);
  return [gridStart.toISOString(), gridEnd.toISOString()];
}

export default async function CalendarPage() {
  await requireUser();

  let calendars: CalendarInfo[] = [];
  let events: CalEvent[] = [];
  let tasks: TaskItem[] = [];
  let failed = false;

  try {
    calendars = await listCalendars();
    if (calendars.length > 0) {
      const [start, end] = initialRange();
      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
    }
  } catch {
    failed = true;
  }

