  const ticket = await db.ticket.findUnique({
    where: { id },
    include: {
      messages: {
        select: {
          id: true,
          body: true,
          isStaff: true,
          authorId: true,
          createdAt: true,
          editedAt: true,
          attachmentMime: true,
          attachmentName: true,
          attachmentSize: true,
          author: true,
        },
        orderBy: { createdAt: "asc" },
      },
